1	import { defaultScenario } from "./default.ts";
2	import { ordersScenario } from "./orders.ts";
3	import { productMediaTranslationsScenario } from "./productMediaTranslations.ts";
4	import type { Scenario } from "./scenario.ts";
5	
6	/** Every scenario a spec may ask for by name, via `test.use({ scenario: "..." })`. */
7	export const SCENARIOS: Record<string, Scenario> = {
8	  [defaultScenario.name]: defaultScenario,
9	  [ordersScenario.name]: ordersScenario,
10	  [productMediaTranslationsScenario.name]: productMediaTranslationsScenario,
11	};
12	
13	export const scenarioByName = (name: string): Scenario => {
14	  const scenario = SCENARIOS[name];
15	
16	  if (!scenario) {
17	    throw new Error(`unknown scenario "${name}" - known: ${Object.keys(SCENARIOS).join(", ")}`);
18	  }
19	
20	  return scenario;
21	};
