1	import { type Page } from "@playwright/test";
2	
3	import { AddressDialog } from "./addressDialog.ts";
4	
5	/**
6	 * A placed order: payment, fulfillment, tracking and addresses. Ported from the legacy
7	 * `OrdersPage` and its dialogs; the locators carry over, except that tracking now lives in
8	 * the timeline view of the order's lines, which is not the default.
9	 */
10	export class OrderPage {
11	  readonly addressDialog = new AddressDialog(this.page);
12	
13	  readonly dialog = this.page.getByRole("dialog");
14	
15	  readonly statusInfo = this.page.getByTestId("status-info");
16	
17	  readonly markAsPaidButton = this.page.getByTestId("mark-as-paid-button");
18	
19	  readonly transactionReferenceInput = this.page.getByTestId("transaction-reference-input");
20	
21	  readonly paymentStatusBadges = this.page.getByTestId("payment-status-badges");
22	
23	  readonly transactions = this.page.getByTestId("orderTransactionsList");
24	
25	  readonly manualTransactionButton = this.page.getByTestId("captureManualTransactionButton");
26	
27	  readonly transactionDescriptionInput = this.page.getByTestId("transactionDescription");
28	
29	  readonly transactionAmountInput = this.page.getByTestId("transactAmountInput");
30	
31	  readonly manualTransactionSubmit = this.page.getByTestId("manualTransactionSubmit");
32	
33	  readonly fulfillButton = this.page.getByTestId("order-items-fulfill-button");
34	
35	  readonly confirmFulfillmentButton = this.page.getByTestId("button-bar-confirm");
36	
37	  readonly timelineView = this.page.getByTestId("order-items-view-timeline");
38	
39	  readonly addTrackingButton = this.page.getByTestId("add-tracking-button");
40	
41	  readonly trackingNumberInput = this.page.getByTestId("tracking-number-input");
42	
43	  readonly confirmTrackingButton = this.page.getByTestId("confirm-tracking-number-button");
44	
45	  readonly trackingNumber = this.page.getByTestId("tracking-number-set");
46	
47	  readonly total = this.page.getByTestId("order-total");
48	
49	  readonly shippingAddressSection = this.page.getByTestId("shipping-address-section");
50	
51	  readonly billingAddressSection = this.page.getByTestId("billing-address-section");
52	
53	  readonly editShippingAddressButton = this.page.getByTestId("edit-shipping-address");
54	
55	  readonly editBillingAddressButton = this.page.getByTestId("edit-billing-address");
56	
57	  constructor(readonly page: Page) {}
58	
59	  async goto(orderId: string) {
60	    await this.page.goto(`/orders/${orderId}`);
61	    await this.statusInfo.waitFor();
62	  }
63	
